import csv
import io


def _parse_value(value):
    """Convert a CSV cell to a number if possible, otherwise a string.
    Empty cells (or None) become None."""
    if value is None:
        return None
    if value == '':
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


def merge_csv_texts(csv_texts):
    # First pass: collect the union of all headers, preserving first-seen order.
    all_columns = []
    seen = set()
    for text in csv_texts:
        if not text or not text.strip():
            continue
        reader = csv.reader(io.StringIO(text))
        header = next(reader, None)
        if header is None:
            continue
        for col in header:
            if col not in seen:
                seen.add(col)
                all_columns.append(col)

    result = []
    # Second pass: stack the data rows in input order.
    for text in csv_texts:
        if not text or not text.strip():
            continue
        reader = csv.reader(io.StringIO(text))
        header = next(reader, None)
        if header is None:
            continue
        for row in reader:
            if not row or row == ['']:  # skip blank lines
                continue
            record = {col: None for col in all_columns}
            for col, value in zip(header, row):
                record[col] = _parse_value(value)
            result.append(record)

    return result
```

Example usage:

```python
texts = ['Name,Age\nAlice,25', 'Name,Age,City\nBob,30,Paris']
print(merge_csv_texts(texts))
# [{'Name': 'Alice', 'Age': 25, 'City': None},
#  {'Name': 'Bob', 'Age': 30, 'City': 'Paris'}]

print(merge_csv_texts([]))
# []
```

How it works:

1. **Header union (first pass):** It scans every document's header row and builds the set of all columns across the inputs, in the order they first appear.
2. **Row stacking (second pass):** Each document's data rows are appended in order. Every row starts as a dict with all columns set to `None`, then the values from that row's own file are filled in — so columns missing from a row's file stay `None`.
3. **Value conversion:** Cells are converted to `int` first, then `float` (so `25` stays an integer while `3.5` becomes a float), and anything non-numeric stays a string. Empty cells become `None`.
4. **Edge cases:** Blank input texts, documents without any rows, and blank lines within documents are all handled gracefully; an empty input list yields an empty result.

```python
def letter_count_correlations(strings):
    if not strings:
        return None

    n = len(strings)

    # Collect all letters that appear anywhere in the input
    letters = sorted(set("".join(strings)))

    # Per-string counts for each letter
    counts = {ch: [s.count(ch) for s in strings] for ch in letters}

    # Means
    means = {ch: sum(vals) / n for ch, vals in counts.items()}

    # Standard deviations (needed for every letter, computed once)
    stds = {}
    for ch in letters:
        var = sum((v - means[ch]) ** 2 for v in counts[ch]) / n
        stds[ch] = var ** 0.5

    # Pairwise Pearson correlations
    result = {}
    for x in letters:
        row = {}
        for y in letters:
            cov = sum(
                (counts[x][i] - means[x]) * (counts[y][i] - means[y])
                for i in range(n)
            ) / n
            row[y] = cov / (stds[x] * stds[y])
        result[x] = row

    return result
```

**How it works:**

1. **Empty input** — return `None` immediately.
2. **Letter set** — `set("".join(strings))` finds every letter that occurs in at least one string; letters never seen are excluded.
3. **Count vectors** — for each letter, we build a vector of its count in each string, e.g. for `['ab', 'ba', 'cc']`, the letter `'c'` gets `[0, 0, 2]`.
4. **Pearson correlation** — computed as `cov(X, Y) / (σ_X · σ_Y)` using population statistics (dividing sums by `n`). Since each letter's count varies across strings (given as an assumption), the standard deviations are nonzero, so no division-by-zero handling is needed.

**Example:**

```python
print(letter_count_correlations(['ab', 'ba', 'cc']))
# {'a': {'a': 1.0, 'b': 1.0, 'c': -1.0},
#  'b': {'a': 1.0, 'b': 1.0, 'c': -1.0},
#  'c': {'a': -1.0, 'b': -1.0, 'c': 1.0}}
```

Here `a` and `b` always co-occur (correlation `1.0`), while `c` appears only when `a`/`b` don't (correlation `-1.0`) — matching the expected output. The structure is symmetric and the diagonal is always `1.0`.

