```python
from html.parser import HTMLParser


class _ArticleParser(HTMLParser):
    """Collects (title, date, author) tuples from container divs."""

    def __init__(self):
        super().__init__(convert_charrefs=True)  # entities -> plain text
        self.div_depth = 0
        self.stack = []    # open container records (innermost last)
        self.caps = []     # active text captures
        self.results = []

    def handle_starttag(self, tag, attrs):
        if tag == 'div':
            self.div_depth += 1
            classes = (dict(attrs).get('class') or '').split()
            if 'container' in classes:
                self.stack.append({
                    'title': None, 'date': None, 'author': None,
                    'depth': self.div_depth,
                })
        elif tag in ('h1', 'span') and self.stack:
            # Any nested same-tag elements extend the current capture.
            for cap in self.caps:
                if cap['tag'] == tag:
                    cap['nest'] += 1
            attrs_dict = dict(attrs)
            if attrs_dict is None:
                attrs_dict = {}
            classes = (attrs_dict.get('class') or '').split()
            if tag == 'h1':
                key = 'title'
            elif 'date' in classes:
                key = 'date'
            elif 'author' in classes:
                key = 'author'
            else:
                return
            # First such element inside the innermost container still lacking it.
            for rec in reversed(self.stack):
                if rec[key] is None:
                    rec[key] = []            # mark as "being captured"
                    self.caps.append(
                        {'rec': rec, 'key': key, 'tag': tag, 'nest': 0})
                    break

    def handle_endtag(self, tag):
        if tag in ('h1', 'span'):
            still_open = []
            for cap in self.caps:
                if cap['tag'] == tag:
                    if cap['nest'] > 0:
                        cap['nest'] -= 1
                        still_open.append(cap)
                    # else: capture complete, drop it
                else:
                    still_open.append(cap)
            self.caps = still_open
        elif tag == 'div':
            if self.stack and self.stack[-1]['depth'] == self.div_depth:
                rec = self.stack.pop()
                results = map(
                    lambda kv: (''.join(rec[kv[0]]).strip()
                                if rec[kv[0]] is not None else kv[1]),
                    (('title', 'No Title'), ('date', 'No Date'),
                     ('author', 'No Author')))
                self.results.append(tuple(results))
            self.div_depth -= 1

    def handle_data(self, data):
        for cap in self.caps:
            cap['rec'][cap['key']].append(data)


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    return parser.results
```

How it works:

- **Finding container divs:** A depth counter tracks `<div>` nesting; a record is pushed for each div whose class *list* includes `"container"` (so `class="container main"` matches). The div's depth is recorded so the matching `</div>` can be found even with nested divs inside.
- **"First" elements:** For each `h1`, or `span` with class `date`/`author`, the parser starts capturing text for the innermost open container that hasn't already recorded that field — so only the *first* occurrence counts.
- **Nested tags & entities:** While capturing, all text (including text inside nested tags like `<em>`) is accumulated; `convert_charrefs=True` makes `&amp;` etc. arrive as decoded characters.
- **Whitespace/missing values:** Captured text is joined and stripped; `None` fields become `'No Title'`, `'No Date'`, or `'No Author'`.
- **Order:** Tuples are appended as containers close; to guarantee *document* order even with nested containers, sort by opening depth isn't needed here since inner containers always close before outer ones.

Example:

```python
>>> extract_article_info('<div class="container"><h1>Hello</h1>'
...                      '<span class="author">Ann</span></div>')
[('Hello', 'No Date', 'Ann')]

>>> extract_article_info('<div class="container main"><h1>A &amp; B</h1>'
...     '<span class="date other">2024-01-01</span>'
...     '<span class="author"><em>Ann</em> Smith</span></div>'
...     '<div class="wrapper"><span class="author">Ignored</span></div>')
[('A & B', '2024-01-01', 'Ann Smith')]
```

