import json
import math


def key_mean_median(json_text):
    records = json.loads(json_text)

    # Collect numeric values per key, preserving first-appearance key order.
    values = {}
    for record in records:
        for key, value in record.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                continue
            # Rule out non-finite numbers (nan / inf) just in case.
            if isinstance(value, float) and not math.isfinite(value):
                continue
            values.setdefault(key, []).append(value)

    result = {}
    for key, nums in values.items():
        if not nums:
            result[key] = {'mean': None, 'median': None}
            continue

        n = len(nums)
        mean = sum(nums) / n
        sorted_nums = sorted(nums)
        mid = n // 2
        if n % 2 == 1:
            median = float(sorted_nums[mid])
        else:
            median = (sorted_nums[mid - 1] + sorted_nums[mid]) / 2
        result[key] = {'mean': mean, 'median': median}

    return result
```

