def merge_and_standardize(rows1, rows2):
    # Feature columns of each table (everything except 'id')
    cols1 = [c for c in (rows1[0] if rows1 else {}) if c != 'id']
    cols2 = [c for c in (rows2[0] if rows2 else {}) if c != 'id']
    # Be safe if rows don't share keys uniformly: gather from all rows
    for r in rows1:
        for c in r:
            if c != 'id' and c not in cols1:
                cols1.append(c)
    for r in rows2:
        for c in r:
            if c != 'id' and c not in cols2:
                cols2.append(c)

    # Standardization stats for table 1 (ignore missing values)
    stats = {}
    for col in cols1:
        vals = [r[col] for r in rows1 if r.get(col) is not None]
        n = len(vals)
        mean = sum(vals) / n if n else 0.0
        var = sum((v - mean) ** 2 for v in vals) / n if n else 0.0
        std = var ** 0.5
        stats[col] = (mean, std)

    def standardize(col, value):
        if value is None:
            return None
        mean, std = stats[col]
        if std == 0:
            return 0.0
        return (value - mean) / std

    # Outer join on 'id'
    rows_by_id = {}
    for r in rows1:
        rid = r['id']
        row = {'id': rid}
        for col in cols1:
            row[col] = standardize(col, r.get(col))
        for col in cols2:
            row[col] = None
        rows_by_id[rid] = row

    for r in rows2:
        rid = r['id']
        if rid not in rows_by_id:
            row = {'id': rid}
            for col in cols1:
                row[col] = None
            rows_by_id[rid] = row
        for col in cols2:
            rows_by_id[rid][col] = r.get(col)

    return [rows_by_id[rid] for rid in sorted(rows_by_id)]
```

