import xml.etree.ElementTree as ET


def xml_to_dict(xml):
    """Parse an XML string into nested Python dicts.

    Returns {root_tag: value}. An element with no attributes and no
    children becomes its trimmed text (or None if it has no text).
    Any other element becomes a dict with attributes as '@key' entries,
    child elements keyed by tag, and text under '#text'. Repeated
    sibling tags become lists of their values in document order.

    Raises ValueError if the XML is malformed.
    """
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as e:
        raise ValueError(f"Malformed XML: {e}") from e

    def convert(elem):
        attrs = {'@' + key: value for key, value in elem.attrib.items()}
        children = list(elem)

        # Leaf element: plain text (or None).
        if not attrs and not children:
            if elem.text is None:
                return None
            return elem.text.strip()

        result = dict(attrs)
        for child in children:
            value = convert(child)
            if child.tag in result:
                existing = result[child.tag]
                if not isinstance(existing, list):
                    result[child.tag] = [existing]
                result[child.tag].append(value)
            else:
                result[child.tag] = value

        if elem.text is not None:
            text = elem.text.strip()
            if text:
                result['#text'] = text

        return result

    return {root.tag: convert(root)}
```

Examples:

```python
>>> xml_to_dict('<family><person name="John"><age>30</age></person>'
...             '<person name="Jane"/></family>')
{'family': {'person': [{'@name': 'John', 'age': '30'}, {'@name': 'Jane'}]}}

>>> xml_to_dict('<a>hello</a>')
{'a': 'hello'}

>>> xml_to_dict('<a/>')
{'a': None}

>>> xml_to_dict('<a x="1">text<b>inner</b></a>')
{'a': {'@x': '1', 'b': 'inner', '#text': 'text'}}

>>> xml_to_dict('<a><b/><b>2</b></a>')
{'a': {'b': [None, '2']}}

>>> xml_to_dict('<a><b>')
Traceback (most recent call last):
    ...
ValueError: Malformed XML: ...
```

**Notes on behavior:**

- Whitespace-only text on a mixed/attributed element is ignored (no `'#text'` key added), so formatting newlines between child elements don't pollute the output.
- Repeated sibling tags always produce a list in document order, even if there are only two occurrences or the first value is `None`.
- Any `ET.ParseError` (including the empty string) is re-raised as a `ValueError`, with the original parse message preserved for easier debugging.

