import math
import re


def bracket_free_tfidf(texts):
    def strip_brackets(s):
        # Repeatedly remove innermost bracket groups (handles nesting too)
        prev = None
        while prev != s:
            prev = s
            s = re.sub(r'\[[^\[\]]*\]', ' ', s)
        return s

    # Tokenise each text after removing bracketed content
    docs = []
    for text in texts:
        cleaned = strip_brackets(text).lower()
        words = re.findall(r'[a-z0-9_]{2,}', cleaned)
        docs.append(words)

    n = len(docs)

    # Document frequency for each word
    df = {}
    for words in docs:
        for w in set(words):
            df[w] = df.get(w, 0) + 1

    results = []
    for words in docs:
        # Raw term counts
        counts = {}
        for w in words:
            counts[w] = counts.get(w, 0) + 1

        # TF-IDF with smoothed idf: ln((1+n)/(1+df)) + 1
        scores = {
            w: c * (math.log((1 + n) / (1 + df[w])) + 1)
            for w, c in counts.items()
        }

        # L2 normalisation
        norm = math.sqrt(sum(v * v for v in scores.values()))
        if norm > 0:
            scores = {w: v / norm for w, v in scores.items()}
        else:
            scores = {}

        results.append(scores)

    return results
```

Example:

```python
>>> bracket_free_tfidf(['Alice Bob [x]', 'Bob Alice Alice'])
[{'alice': 0.7071067811865475, 'bob': 0.7071067811865475},
 {'alice': 0.8944271909999159, 'bob': 0.4472135954999579}]
```

How it works:

1. **Bracket stripping**: nested-bracket-safe removal of `[...]` groups; here `[x]` is dropped (and `x` alone wouldn't count as a word anyway, since words need ≥ 2 characters).
2. **Tokenisation**: runs of two or more letters/digits/underscores, lowercased.
3. **TF**: raw counts within each string.
4. **IDF**: smoothed `ln((1+n)/(1+df)) + 1`, where `n` is the total number of strings — in the example both words appear in both strings, so idf = `ln(3/3)+1 = 1`.
5. **Normalisation**: each string's vector is scaled to unit Euclidean length; strings with no valid words yield `{}`.

