import math


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")

    def replace(value):
        return mapping[value] if value in mapping else value

    # Apply the mapping so every value is numeric
    numeric = {
        col: [replace(v) for v in values]
        for col, values in data.items()
    }

    def pearson(xs, ys):
        n = len(xs)
        mean_x = sum(xs) / n
        mean_y = sum(ys) / n
        cov = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
        var_x = sum((x - mean_x) ** 2 for x in xs)
        var_y = sum((y - mean_y) ** 2 for y in ys)
        denom = math.sqrt(var_x * var_y)
        if denom == 0:
            # A constant column has correlation 1 with itself, 0 with others
            return 1.0 if xs is ys else 0.0
        return cov / denom

    result = {}
    for a in numeric:
        result[a] = {}
        for b in numeric:
            if a == b:
                # Correlation of a column with itself; still compute so that
                # constant columns are handled consistently
                result[a][b] = 1.0
            else:
                result[a][b] = pearson(numeric[a], numeric[b])
    return result
```

Example:

```python
mapped_correlation_matrix({'m': ['lo', 'lo', 'hi'], 'n': [5, 3, 5]}, {'lo': 1, 'hi': 2})
# {'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}
```

How it works:

1. **Validation**: raises `ValueError` if `data` is not a dict.
2. **Mapping**: each value is looked up in `mapping`; keys are replaced with their mapped values, everything else passes through unchanged (so already-numeric values are fine).
3. **Pearson correlation**: for each pair of columns \((a, b)\), the correlation is computed as
   \[
   \rho_{a,b} = \frac{\sum (x_i - \bar{x})(y_i - \bar{y})}{\sqrt{\sum (x_i - \bar{x})^2 \sum (y_i - \bar{y})^2}}
   \]
4. **Degenerate case**: a constant column has zero variance; its self-correlation is defined as `1.0` and its correlation with other columns as `0.0` (avoiding division by zero).

# Solution

```python
from datetime import date, datetime, timedelta
import calendar

WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3,
            'FRI': 4, 'SAT': 5, 'SUN': 6}


def forecast_schedule(start_date, freq, sales):
    # --- validate start date (raises ValueError if malformed) ---
    start = datetime.strptime(start_date, '%Y-%m-%d').date()

    # --- validate and parse freq ---
    if freq in ('month-end', 'quarter-end'):
        nth, weekday = None, None
    else:
        parts = freq.split('-')
        if len(parts) != 2:
            raise ValueError(f"Invalid freq: {freq!r}")
        try:
            nth = int(parts[0])
        except ValueError:
            raise ValueError(f"Invalid freq: {freq!r}")
        weekday = parts[1].upper()
        if not (1 <= nth <= 4) or weekday not in WEEKDAYS:
            raise ValueError(f"Invalid freq: {freq!r}")

    def nth_weekday_of_month(year, month, week, wd):
        """Date of the `week`-th occurrence of weekday `wd` in a month."""
        first = date(year, month, 1)
        offset = (wd - first.weekday()) % 7
        return first + timedelta(days=offset + 7 * (week - 1))

    def candidate_dates():
        """Yield every date matching freq, in order, from start's month on."""
        year, month = start.year, start.month
        while True:
            if freq == 'month-end':
                yield date(year, month, calendar.monthrange(year, month)[1])
            elif freq == 'quarter-end':
                if month in (3, 6, 9, 12):
                    yield date(year, month, calendar.monthrange(year, month)[1])
            else:  # e.g. '2-FRI'
                yield nth_weekday_of_month(year, month, nth, WEEKDAYS[weekday])
            month += 1
            if month == 13:
                month, year = 1, year + 1

    # Collect the first len(sales) matching dates on/after start_date.
    dates = []
    for d in candidate_dates():
        if d >= start:
            dates.append(d)
            if len(dates) == len(sales):
                break

    return [(d.isoformat(), s) for d, s in zip(dates, sales)]
```

## How it works

1. **Start date validation** — `datetime.strptime(start_date, '%Y-%m-%d')` raises `ValueError` for anything that isn't a valid `YYYY-MM-DD` date.
2. **Freq parsing** — `'month-end'` and `'quarter-end'` are handled specially; otherwise the code expects `'<week>-<WEEKDAY>'` with week 1–4 and a weekday code, raising `ValueError` otherwise.
3. **Date generation** — a generator walks month by month from the start month, yielding every date that matches the frequency:
   - month-end: last day of the month via `calendar.monthrange`;
   - quarter-end: last day of Mar/Jun/Sep/Dec (other months are skipped);
   - `n-WKD`: first day of the month, shifted to the first occurrence of the weekday, plus `7 * (n - 1)` days.
4. **Selection** — dates before `start_date` are skipped; exactly `len(sales)` dates are collected, then zipped with the sales figures.

