import csv
import io

def grouped_column_means(csv_text, group_col, value_col):
    """
    Group rows of a CSV (given as text, with a header row) by the value
    in `group_col` and return a dict mapping each group label (as a
    string) to the mean of the `value_col` values in that group.

    - Blank cells in the value column are ignored (not counted).
    - A non-numeric value in the value column raises ValueError.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    try:
        group_idx = header.index(group_col)
    except ValueError:
        raise ValueError(f"Column not found in header: {group_col!r}")

    try:
        value_idx = header.index(value_col)
    except ValueError:
        raise ValueError(f"Column not found in header: {value_col!r}")

    sums = {}
    counts = {}

    for row_num, row in enumerate(reader, start=2):  # line 2 = first data row
        if not row or len(row) <= max(group_idx, value_idx):
            continue
        group = row[group_idx]
        raw_value = row[value_idx].strip()

        if raw_value == "":
            continue  # ignore blank cells

        try:
            value = float(raw_value)
        except ValueError:
            raise ValueError(
                f"Non-numeric value {raw_value!r} in column "
                f"{value_col!r} on line {row_num}"
            )

        sums[group] = sums.get(group, 0.0) + value
        counts[group] = counts.get(group, 0) + 1

    return {group: sums[group] / counts[group] for group in sums}
```

