import re

_WS = b' \t\r\n\x0b\x0c'   # whitespace characters allowed in a PNM header


def grayscale_histogram(data):
    """
    Parse the raw bytes of an 8-bit grayscale PGM image (binary P5 or
    ASCII P2 variant) and return a histogram of its pixel values as a
    dict {pixel_value: count}. Only values that actually occur appear
    as keys. Raises ValueError if the bytes are not a valid image.
    """
    if isinstance(data, bytearray):
        buf = bytes(data)
    elif isinstance(data, bytes):
        buf = data
    else:
        raise ValueError("input must be bytes")

    n = len(buf)
    i = 0

    def next_token():
        """Return the next header token, skipping whitespace and comments."""
        nonlocal i
        while i < n:
            c = buf[i]
            if c in _WS:
                i += 1
            elif c == 0x23:  # '#': comment runs to end of line
                while i < n and buf[i] not in b'\r\n':
                    i += 1
            else:
                break
        if i >= n:
            raise ValueError("unexpected end of file in header")
        start = i
        while i < n and buf[i] not in _WS:
            i += 1
        return buf[start:i]

    def next_int():
        tok = next_token()
        try:
            return int(tok)
        except ValueError:
            raise ValueError("invalid header field: %r" % tok)

    # --- Header ------------------------------------------------------
    magic = next_token()
    if magic == b'P5':
        binary = True
    elif magic == b'P2':
        binary = False
    else:
        raise ValueError("not a PGM file (magic %r)" % magic)

    width = next_int()
    height = next_int()
    maxval = next_int()

    if width <= 0 or height <= 0:
        raise ValueError("invalid dimensions")
    if not (0 < maxval <= 255):
        raise ValueError("unsupported maxval (must be 1..255 for 8-bit)")

    num_pixels = width * height
    hist = {}

    if binary:
        # P5: exactly one whitespace character separates the header
        # from the raster data.
        if i >= n or buf[i] not in _WS:
            raise ValueError("missing whitespace after maxval")
        i += 1

        raster = buf[i:i + num_pixels]
        if len(raster) != num_pixels:
            raise ValueError("raster data truncated")
        if len(buf) - i != num_pixels:
            raise ValueError("unexpected trailing bytes after raster data")

        for b in raster:
            if b > maxval:
                raise ValueError("pixel value %d exceeds maxval %d" % (b, maxval))
            hist[b] = hist.get(b, 0) + 1
    else:
        # P2: the rest of the file consists of ASCII integers
        # (whitespace-separated; comments allowed).
        j = i
        count = 0
        while j < n:
            c = buf[j]
            if c in _WS:
                j += 1
            elif c == 0x23:  # comment
                while j < n and buf[j] not in b'\r\n':
                    j += 1
            else:
                start = j
                while j < n and buf[j] not in _WS:
                    j += 1
                try:
                    v = int(buf[start:j])
                except ValueError:
                    raise ValueError("invalid pixel value: %r" % buf[start:j])
                if v < 0 or v > maxval:
                    raise ValueError("pixel value %d out of range" % v)
                hist[v] = hist.get(v, 0) + 1
                count += 1
        if count != num_pixels:
            raise ValueError("expected %d pixel values, found %d"
                             % (num_pixels, count))

    return hist
```

