print(result)
# {'means': {'A': 2.0, 'B': 5.0}, 'std_devs': {'A': 1.0, 'B': 1.0}, 'f_value': 13.5}

# Thousands separators + a non-numeric column
print(summarize_numeric_csv('X,Label\n"1,000",a\n2,000,b\n'))
# {'means': {'X': 1500.0}, 'std_devs': {'X': 500.0}, 'f_value': None}

# One bad cell disqualifies the whole column
