import math


def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    lengths = {len(col) for col in table.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("table is empty")

    def is_numeric(col):
        return all(
            isinstance(x, (int, float)) and not isinstance(x, bool)
            for x in col
        )

    numeric_keys = [k for k, col in table.items() if is_numeric(col)]
    if not numeric_keys:
        raise ValueError("table has no numeric columns")

    # Means and population standard deviations of numeric columns.
    means = {}
    stds = {}
    for k in numeric_keys:
        col = table[k]
        m = sum(col) / n
        s = math.sqrt(sum((x - m) ** 2 for x in col) / n)
        means[k] = m
        stds[k] = s

    # Build the standardized table, preserving column order.
    standardized = {}
    for k, col in table.items():
        if k in means:
            m, s = means[k], stds[k]
            standardized[k] = [(x - m) / s if s != 0 else 0.0 for x in col]
        else:
            standardized[k] = list(col)

    # Pearson correlation matrix (population covariance / product of stds).
    corr = []
    for a in numeric_keys:
        row = []
        for b in numeric_keys:
            if a == b:
                row.append(1.0)
            else:
                s_a, s_b = stds[a], stds[b]
                if s_a == 0 or s_b == 0:
                    row.append(0.0)
                else:
                    cov = sum(
                        (x - means[a]) * (y - means[b])
                        for x, y in zip(table[a], table[b])
                    ) / n
                    row.append(cov / (s_a * s_b))
        corr.append(row)

    return standardized, corr
```

Example:

```python
standardize_and_correlate({'x': [1, 2, 3], 'n': ['a', 'b', 'c'], 'y': [3, 1, 2]})
# ({'x': [-1.224744871391589, 0.0, 1.224744871391589],
#   'n': ['a', 'b', 'c'],
#   'y': [1.224744871391589, -1.2247448713915888, 0.0]},
#  [[1.0, -0.5], [-0.5, 1.0]])
```

Notes on the design:

- **Numeric detection**: a column is numeric if every value is an `int` or `float` (booleans are excluded since they're technically ints in Python).
- **Population std**: variance divides by `n` (not `n - 1`), matching the example values (e.g., ±1.2247… = ±1/√(2/3)).
- **Column order**: `standardized` and `corr` follow the dict's insertion order (Python 3.7+).
- **Edge cases**: an empty dict, zero-length columns, mismatched column lengths, or no numeric columns all raise `ValueError`. A constant (zero-variance) numeric column is standardized to zeros and correlated as `0.0` with other columns to avoid division by zero; its diagonal entry is `1.0`.
- **Correlation math**: computed from the original data as `cov(X, Y) / (σ_X · σ_Y)`, which is equivalent to using the standardized values and keeps the diagonal exactly `1.0`.

Here's a clean implementation using Python's standard library:

```python
import json
from html.parser import HTMLParser


class _TitleParser(HTMLParser):
    """Parses HTML, capturing the text of the first <title> element."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.in_title = False
        self.title_parts = []
        self.done = False

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "title" and not self.done:
            self.in_title = True
            self.title_parts = []

    def handle_endtag(self, tag):
        if tag.lower() == "title" and self.in_title:
            self.in_title = False
            self.done = True

    def handle_data(self, data):
        if self.in_title and not self.done:
            self.title_parts.append(data)

    def handle_entityref(self, name):
        if self.in_title and not self.done:
            self.title_parts.append(f"&{name};")

    def handle_charref(self, name):
        if self.in_title and not self.done:
            self.title_parts.append(f"&#{name};")


def extract_title_json(html):
    """Extract the first <title> element's text from HTML markup.

    Returns a JSON string of the form '{"title": ...}' where the value
    is the entity-decoded title text, or null if no title exists.
    """
    parser = _TitleParser()
    parser.feed(html)
    parser.close()

    if parser.done and parser.title_parts:
        title = html.unescape("".join(parser.title_parts)).strip()
    else:
        title = None

    return json.dumps({"title": title})
```

**Example usage:**

```python
print(extract_title_json("<html><head><title>Hello World</title></head></html>"))
# {"title": "Hello World"}

print(extract_title_json("<title>Caf&eacute; &amp; Bar</title>"))
# {"title": "Café & Bar"}

print(extract_title_json("<html><body><p>No title here</p></body></html>"))
# {"title": null}

print(extract_title_json("<title>First</title><title>Second</title>"))
# {"title": "First"}
```

**How it works:**

1. **`_TitleParser`** subclasses `HTMLParser` to walk the markup. The `done` flag ensures only the *first* `<title>` element is captured, even if others appear later (or a stray end tag shows up after the element).

2. **Entity handling:** `convert_charrefs=False` keeps entity references intact during parsing so we can reconstruct the raw text, then `html.unescape()` decodes entities (`&amp;`, `&#225;`, etc.) in one pass after collecting the text.

3. **JSON output:** `json.dumps` handles proper escaping of quotes, backslashes, and non-ASCII characters in the final output. If no title element was found (or the title is empty), the value is `null`.

One nuance: an empty `<title></title>` yields `null` here (the element exists but has no text). If you'd rather return `{"title": ""}` in that case, change the condition to `if parser.done:` and drop the `title_parts` check.

